function NewDefine(filein)
  isTonumber=gg.alert("Whether to use tonumber to encrypt the string?","(Recommended) yes","no")
  files1=io.open(filein)
  s=0
  Stable={}
  local New_sprit=""
  repeat
    text=text or ""
    text=files1:read('*l')
    if text and text~="" then
      s=s+1
      Stable[s]=text
    end
  until text==nil
  for s=1,#Stable do
    if Stable[s]~="" and Stable[s+1] then
      if not Stack then
       else
        STr=STr..Stable[s].."\n"
        Stable[s]=""
        if Stable[s+1]:find("xqmnb") then
          pcall(load(STr))
          STr=xqmnb()
          if Stable[s+1]:find("end") then STr=STr.."\nend" end
          Stable[s+1]=STr
          Stack=nil
        end
      end
    end
    if Stable[s]:find("qmnb") and load(Stable[s].."}") and not Stack then
      Stack=true
      STr=Stable[s].."\n"
      Stable[s]=""
    end
  end
  for s=1,#Stable do
    if Stable[s]~="" and Stable[s+3] then
      local FF=load(Stable[s]..Stable[s+1]..Stable[s+2]..Stable[s+3])
      if FF and Stable[s]:find("searchNumber") and Stable[s+1]:find("searchNumber") and Stable[s+2]:find("getResults") and Stable[s+3]:find("editAll") then
        STr=""
        Trefine={}
        pcall(FF)
        if STr~="" then
          Stable[s]=STr
          Stable[s+1]=""
          Stable[s+2]=""
          Stable[s+3]=""
        end
      end
    end
  end
  for s=1,#Stable do
    if Stable[s]~="" then
      New_sprit=New_sprit..Stable[s].."\n"
    end
  end
  return New_sprit
end

