local function chitamytpro(str1,str2,str3)
  local Er=Gginfo[1]..Gginfo[3]..Gginfo[2]..(tonumber(Gginfo[2])*100)
  str2=str2 or Er
  str3=str3 or Er
  local hexget_int=0
  local counti={str1:byte(0,-1)}
  for kvb=1,#counti do
    hexget_int=hexget_int+counti[kvb]+kvb
  end
  local str_bytes={(str1..str2..str3):byte(0,-1)}
  while #str_bytes>10 do
    local len_bytes=#str_bytes
    local bytes_temp={}
    if len_bytes%2~=0 then
      len_bytes=len_bytes+1
      str_bytes[len_bytes]=42
    end
    for s_=1,len_bytes/2 do
      bytes_temp[s_]=(str_bytes[s_]+str_bytes[len_bytes-s_+1])/2+hexget_int
    end
    str_bytes=bytes_temp
  end
  hexget_int=0
  for s=1,10 do
    hexget_int=hexget_int==#str_bytes and 1 or hexget_int+1
    str_bytes[s]=str_bytes[hexget_int]+s
  end
  return str_bytes
end

